def _db(ws):
    return Path(ws).parent / "system" / "servicenow_hrsd_actions" / "state.db"


def _connect(ws):
    connection = sqlite3.connect(f"file:{_db(ws)}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    return connection


def _norm(value):
    return re.sub(r"[^a-z0-9]+", " ", str(value or "").lower()).strip()


def _as_date(value):
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if value is None:
        return None
    text = str(value).strip()
    for fmt in ("%Y-%m-%d", "%Y-%m-%d %H:%M:%S", "%m/%d/%Y", "%B %d, %Y", "%d %B %Y"):
        try:
            return datetime.strptime(text, fmt).date()
        except ValueError:
            pass
    return None


def _sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _table_hash(connection, table):
    rows = [dict(row) for row in connection.execute(f"SELECT * FROM {table} ORDER BY 1")]
    payload = json.dumps(rows, sort_keys=True, separators=(",", ":")).encode()
    return hashlib.sha256(payload).hexdigest()


def _target_rows(connection):
    return connection.execute(
        """
        SELECT mc.*
        FROM monitoring_checkins AS mc
        JOIN monitoring_enrollments AS me ON me.enrollment_id = mc.enrollment_id
        JOIN action_cases AS ac ON ac.action_case_id = me.action_case_id
        WHERE ac.case_id = ? AND me.employee_name = ? AND mc.scheduled_date = ?
        ORDER BY mc.checkin_id
        """,
        (CASE_ID, "Nina Patel", TARGET_DATE.isoformat()),
    ).fetchall()


def check_completed_checkin_poststate(ws):
    with _connect(ws) as connection:
        rows = _target_rows(connection)
    if len(rows) != 1:
        return {"score": 0, "detail": f"Expected one Nina Patel check-in on {TARGET_DATE}; found {len(rows)}."}
    row = rows[0]
    expected = {
        "checkin_id": EXPECTED_NEW_ID,
        "enrollment_id": ENROLLMENT_ID,
        "scheduled_date": TARGET_DATE.isoformat(),
        "completed_date": TARGET_DATE.isoformat(),
        "checkin_status": "COMPLETED",
    }
    mismatches = [key for key, value in expected.items() if _norm(row[key]) != _norm(value)]
    if mismatches:
        return {"score": 0, "detail": f"Completed check-in mismatch in: {', '.join(mismatches)}."}
    return {"score": 1, "detail": f"{EXPECTED_NEW_ID} is the single completed Nina Patel check-in dated 2025-09-26."}


def check_no_retaliation_outcome(ws):
    with _connect(ws) as connection:
        rows = _target_rows(connection)
    if len(rows) != 1:
        return {"score": 0, "detail": "The target check-in is missing or duplicated."}
    row = rows[0]
    if row["retaliation_indicator"] != "NONE_REPORTED" or row["escalation_decision"] != "NO_ESCALATION" or row["escalation_ticket_id"] is not None:
        return {"score": 0, "detail": "The target check-in does not have the required no-reported-concern/no-escalation outcome."}
    note = _norm(row["notes"])
    no_concern = any(term in note for term in ("no retaliation", "no adverse treatment", "no concern", "none reported", "no reported retaliation", "reported no retaliation", "no reported adverse treatment"))
    monitoring_scope = "monitor" in note or "check in" in note or "scheduled" in note
    if not note or not no_concern or not monitoring_scope:
        return {"score": 0, "detail": "The note must concisely document no reported concern and the scheduled monitoring/check-in scope."}
    return {"score": 1, "detail": "The check-in records no reported retaliation, no escalation ticket, and an adequate monitoring note."}


def _tracker_matches(ws):
    path = Path(ws) / TRACKER
    workbook = openpyxl.load_workbook(path, data_only=True, read_only=False)
    sheet = workbook["Control Log"]
    header = {_norm(cell.value): index for index, cell in enumerate(sheet[6], 1)}
    required = ["control date", "control type", "related person", "activity evidence description", "evidence reference"]
    if any(name not in header for name in required):
        return [], "Tracker headers could not be resolved."
    matches = []
    for row_number in range(7, sheet.max_row + 1):
        person = sheet.cell(row_number, header["related person"]).value
        control_type = sheet.cell(row_number, header["control type"]).value
        control_date = sheet.cell(row_number, header["control date"]).value
        if _norm(person) == "nina patel" and _norm(control_type) == "non retaliation check" and _as_date(control_date) == TARGET_DATE:
            description = sheet.cell(row_number, header["activity evidence description"]).value
            reference = sheet.cell(row_number, header["evidence reference"]).value
            matches.append((row_number, _norm(description), _norm(reference)))
    return matches, None


def check_tracker_cross_reference(ws):
    matches, error = _tracker_matches(ws)
    if error:
        return {"score": 0, "detail": error}
    if len(matches) != 1:
        return {"score": 0, "detail": f"Expected one matching tracker evidence line; found {len(matches)}."}
    row_number, description, reference = matches[0]
    combined = f"{description} {reference}"
    if _norm(ORIGINAL_TRACKER_REFERENCE) not in combined:
        return {"score": 0, "detail": "The original tracker evidence reference was not retained."}
    if _norm(EXPECTED_NEW_ID) not in combined:
        return {"score": 0, "detail": "The matching tracker line does not contain the resulting ServiceNow check-in reference."}
    return {"score": 1, "detail": f"Tracker row {row_number} retains the original evidence reference and cross-references {EXPECTED_NEW_ID}."}


def check_existing_monitoring_history_preserved(ws):
    with _connect(ws) as connection:
        rows = connection.execute(
            """
            SELECT mc.*
            FROM monitoring_checkins AS mc
            JOIN monitoring_enrollments AS me ON me.enrollment_id = mc.enrollment_id
            JOIN action_cases AS ac ON ac.action_case_id = me.action_case_id
            WHERE ac.case_id = ?
            ORDER BY mc.checkin_id
            """,
            (CASE_ID,),
        ).fetchall()
    if len(rows) != 5:
        return {"score": 0, "detail": f"Expected four preserved check-ins plus one new check-in; found {len(rows)}."}
    by_id = {row["checkin_id"]: row for row in rows}
    fields = ["enrollment_id", "scheduled_date", "completed_date", "checkin_status", "retaliation_indicator", "escalation_ticket_id", "escalation_decision", "notes"]
    for checkin_id, expected in ORIGINAL_CASE_CHECKINS.items():
        row = by_id.get(checkin_id)
        if row is None or [row[field] for field in fields] != expected:
            return {"score": 0, "detail": f"Existing check-in {checkin_id} was changed or removed."}
    if set(by_id) != set(ORIGINAL_CASE_CHECKINS) | {EXPECTED_NEW_ID}:
        return {"score": 0, "detail": "An unexpected extra case check-in was created."}
    later = by_id[LATER_CHECKIN_ID]
    if later["checkin_status"] != "MISSED" or later["retaliation_indicator"] != "UNKNOWN" or later["escalation_decision"] != "FOLLOW_UP_REQUIRED":
        return {"score": 0, "detail": "Nina Patel's later missed follow-up checkpoint was not preserved."}
    return {"score": 1, "detail": "All pre-existing case check-ins remain unchanged and only the intended record was added."}


def _formula_coordinates(path):
    main_ns = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
    rel_ns = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
    package_ns = "http://schemas.openxmlformats.org/package/2006/relationships"
    formulas = {}
    with zipfile.ZipFile(path) as archive:
        workbook_root = ElementTree.fromstring(archive.read("xl/workbook.xml"))
        rels_root = ElementTree.fromstring(archive.read("xl/_rels/workbook.xml.rels"))
        targets = {
            rel.attrib["Id"]: rel.attrib["Target"]
            for rel in rels_root.findall(f"{{{package_ns}}}Relationship")
        }
        for sheet in workbook_root.find(f"{{{main_ns}}}sheets"):
            sheet_name = sheet.attrib["name"]
            target = targets[sheet.attrib[f"{{{rel_ns}}}id"]].lstrip("/")
            member = target if target.startswith("xl/") else f"xl/{target}"
            sheet_root = ElementTree.fromstring(archive.read(member))
            formulas[sheet_name] = {
                cell.attrib["r"]
                for cell in sheet_root.iter(f"{{{main_ns}}}c")
                if cell.find(f"{{{main_ns}}}f") is not None
            }
    return formulas


def _tracker_literal_hash(path):
    formula_coordinates = _formula_coordinates(path)
    workbook = openpyxl.load_workbook(path, data_only=True, read_only=False)
    values = []
    for sheet in workbook.worksheets:
        for row in sheet.iter_rows():
            for cell in row:
                if sheet.title == "Control Log" and cell.coordinate in {"G59", "H59"}:
                    continue
                if cell.coordinate in formula_coordinates.get(sheet.title, set()):
                    continue
                value = cell.value
                if value is None:
                    continue
                values.append([sheet.title, cell.coordinate, str(value)])
    workbook.close()
    payload = json.dumps(values, ensure_ascii=False, separators=(",", ":")).encode()
    return hashlib.sha256(payload).hexdigest()


def check_unrelated_sources_preserved(ws):
    root = Path(ws)
    for relative, expected in SOURCE_HASHES.items():
        path = root / relative
        if not path.exists() or _sha256(path) != expected:
            return {"score": 0, "detail": f"Unrelated source changed or is missing: {relative}."}
    tracker = root / TRACKER
    if not tracker.exists() or _tracker_literal_hash(tracker) != TRACKER_UNTOUCHED_LITERAL_HASH:
        return {"score": 0, "detail": "Non-target literal content in the corrective-action tracker changed."}
    with _connect(ws) as connection:
        for table, expected in NONCHECKIN_TABLE_HASHES.items():
            if _table_hash(connection, table) != expected:
                return {"score": 0, "detail": f"Unrelated ServiceNow table changed: {table}."}
    return {"score": 1, "detail": "Unrelated source files, tracker content, enrollments, actions, and case records remain unchanged."}
